//! Kai Remote daemon: relays between the bridge webmod (loopback) and phone clients (LAN, token).
mod auth;
mod img;
mod protocol;
mod relay;

use axum::{
    extract::{ws::WebSocketUpgrade, Query, State},
    middleware,
    response::{Html, IntoResponse, Response},
    routing::get,
    Router,
};
use std::{net::SocketAddr, sync::Arc};

const PORT: u16 = 8765;
const INDEX: &str = include_str!("../web/index.html");
// Generated by `npm run build` in remote/web (Tailwind, compiled locally; nothing is loaded from a CDN).
const CSS: &str = include_str!("../web/app.css");
// Lucide icon sprite, generated by the same build.
const ICONS: &str = include_str!("../web/icons.svg");
// cuppa-ui scripts: theme (sync, in <head>) and behaviours (end of <body>).
const THEME_JS: &str = include_str!("../web/ui/theme.js");
const UI_JS: &str = include_str!("../web/ui/ui.js");

async fn index() -> Html<&'static str> {
    Html(INDEX)
}

async fn css() -> impl IntoResponse {
    ([("content-type", "text/css; charset=utf-8"), ("cache-control", "no-cache")], CSS)
}

async fn icons() -> impl IntoResponse {
    ([("content-type", "image/svg+xml"), ("cache-control", "no-cache")], ICONS)
}

async fn theme_js() -> impl IntoResponse {
    ([("content-type", "text/javascript; charset=utf-8"), ("cache-control", "no-cache")], THEME_JS)
}

async fn ui_js() -> impl IntoResponse {
    ([("content-type", "text/javascript; charset=utf-8"), ("cache-control", "no-cache")], UI_JS)
}

async fn bridge_ws(State(app): State<Arc<relay::App>>, ws: WebSocketUpgrade) -> impl IntoResponse {
    ws.on_upgrade(move |s| relay::bridge(app, s))
}

async fn phone_ws(State(app): State<Arc<relay::App>>, ws: WebSocketUpgrade) -> impl IntoResponse {
    ws.on_upgrade(move |s| relay::phone(app, s))
}

async fn img_route(State(app): State<Arc<relay::App>>, Query(q): Query<img::ImgQuery>) -> Response {
    app.img.serve(q).await
}

fn print_pairing(token: &str) {
    let ip = local_ip_address::local_ip().map(|i| i.to_string()).unwrap_or_else(|_| "127.0.0.1".into());
    let url = format!("http://{ip}:{PORT}/?t={token}");
    println!("\nKai Remote listening on 0.0.0.0:{PORT}\nPair your phone: {url}\n");
    if let Ok(code) = qrcode::QrCode::new(url.as_bytes()) {
        use qrcode::render::unicode::Dense1x2;
        println!("{}", code.render::<Dense1x2>().quiet_zone(true).build());
    }
}

#[tokio::main]
async fn main() {
    let app = Arc::new(relay::App::new(auth::load_or_create_token()));
    print_pairing(&app.token);
    let router = Router::new()
        .route("/", get(index))
        .route("/app.css", get(css))
        .route("/icons.svg", get(icons))
        .route("/theme.js", get(theme_js))
        .route("/ui.js", get(ui_js))
        .route("/bridge", get(bridge_ws))
        .route("/img", get(img_route))
        .route("/ws/phone", get(phone_ws))
        .layer(middleware::from_fn_with_state(app.clone(), auth::guard))
        .with_state(app);
    let l = tokio::net::TcpListener::bind(("0.0.0.0", PORT)).await.expect("bind port");
    axum::serve(l, router.into_make_service_with_connect_info::<SocketAddr>()).await.unwrap();
}
